/*
 * A027902  Divisors of 3^24 - 1.
 * https://oeis.org/A027902
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, full, easy
 * Formula:   not stated
 * Range:     u8 n <= 36, u16 n <= 146, u32 n <= 364, u64 n <= 384,
 *            u128 n <= 384, big any n
 * Helpers:   _gen_divs_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: Divisors of 3^24 ‑ 1, sorted ascending (generated by recursive divisor generation) */
#include <stdlib.h>
#include <stdint.h>
#include "../utils/_gen_divs_u64.h"

/* Comparator for qsort on uint64_t values. */
static int _cmp_uint64(const void *a, const void *b)
{
    uint64_t x = *(const uint64_t *)a;
    uint64_t y = *(const uint64_t *)b;
    return (x < y) ? -1 : ((x > y) ? 1 : 0);
}

/* External linkage as required. */
seq_t a(idx_t n)
{
    static int initialized = 0;
    static uint64_t *divs = NULL;
    static size_t div_count = 0;
    /* Prime factorisation of 3^24 ‑ 1 */
    static const uint64_t primes[] = {2ULL, 5ULL, 7ULL, 13ULL, 41ULL, 73ULL, 6481ULL};
    static const int exps[]    = {5, 1, 1, 1, 1, 1, 1};
    enum { NUM_PRIMES = sizeof(primes)/sizeof(primes[0]) };
    enum { MAX_DIVS = 384 };

    if (!initialized) {
        divs = (uint64_t *)malloc(MAX_DIVS * sizeof(uint64_t));
        if (!divs) return 0;            /* allocation failure */
        size_t cnt = 0;
        _gen_divs_u64(0, 1ULL, divs, &cnt, primes, exps, NUM_PRIMES);
        div_count = cnt;                /* should be 384 */
        qsort(divs, div_count, sizeof(uint64_t), _cmp_uint64);
        initialized = 1;
    }

    if (n < 1 || (size_t)n > div_count)
        return 0;                       /* out of range */

    return (seq_t)divs[(size_t)(n - 1)];
}
